actions.command:
current_position = next(song['position'] for song in queue if song['is_current'])
for song in queue:
    if song['position'] <= current_position:
        song_id = song['song_id']
        apis.spotify.like_song(access_token=token, song_id=song_id)
        print(f"Liked song {song_id}")

