    response = apis.spotify.get_user_playlists(username=profile['email'], access_token=token, offset=offset, limit=limit)
    playlists.extend(response['items'])
    if len(response['items']) < limit:
        break
    offset += limit
print(f'Retrieved {len(playlists)} playlists')"}

