actions.command:
classical_artists = set()

# Process first playlist (Ethereal Escapes: Ambient Grooves) songs
for song_id in playlist_library[0]['song_ids']:
    song = apis.spotify.show_song(access_token=spotify_token, song_id=song_id)
    if song['genre'].lower() == 'classical':
        for artist in song['artists']:
            classical_artists.add(artist['id'])

print(f"Classical artists to follow: {classical_artists}")

# Process all playlists in library
for playlist in playlist_library:
    for song_id in playlist['song_ids']:
        song = apis.spotify.show_song(access_token=spotify_token, song_id=song_id)
        if song['genre'].lower() == 'classical':
            for artist in song['artists']:
                classical_artists.add(artist['id'])

# Follow all unique classical artists
for artist_id in classical_artists:
    apis.spotify.follow_artist(access_token=spotify_token, artist_id=artist_id)

print(f"Followed {len(classical_artists)} classical artist(s)")

