        if release_date.split('-')[0] < '2021':
            old_songs.append(song['song_id'])
    page_index += 1
print(f"Found {len(old_songs)} old songs to remove from library")"}

{"code": "old_playlist_songs = {}
page_index = 0
while True:
    playlists = apis.spotify.show_playlist_library(access_token=token, page_index=page_index)
    if not playlists:
        break
    for playlist in playlists:
        playlist_id = playlist['playlist_id']
        old_playlist_songs[playlist_id] = []
        for song_id in playlist['song_ids']:
            song_details = apis.spotify.show_song(song_id=song_id, access_token=token)
            release_date = song_details['release_date']
            if release_date.split('-')[0] < '2021':
                old_playlist_songs[playlist_id].append(song_id)
    page_index += 1
print(f"Found {sum(len(songs) for songs in old_playlist_songs.values())} old songs in playlists")"}

