   "type": "string",
   "required": true,
   "description": "Access token obtained from spotify app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the liked songs by prefixed with +/- to reflect ascending/descending. Valid attributes: liked_at, play_count and title.",
   "default": "-liked_at",
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "song_id": 1,
    "title": "string",
    "album_id": 1,
    "album_title": "string",
    "duration": 1,
    "artists": [
     {
      "id": 1,
      "name": "string"
     }
    ],
    "liked_at": "2019-01-01T00:00:00"
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

actions.command:
# Step 3: Collect unique artist IDs from liked songs
artist_ids = set()
for song in liked_songs:
    for artist in song['artists']:
        artist_ids.add(artist['id'])

# Step 4: Follow each unique artist
for artist_id in artist_ids:
    apis.spotify.follow_artist(access_token=spotify_token, artist_id=artist_id)

# Step 4: Check if already following each artist before following
for artist_id in artist_ids:
    following_status = apis.spotify.show_artist_following(
        access_token=spotify_token, 
        artist_id=artist_id
    )
    if not following_status.get('following', False):
        apis.spotify.follow_artist(
            access_token=spotify_token, 
            artist_id=artist_id
        )

