function.arguments:
{"code": "songs = []
page_index = 0
page_limit = 20
while True:
    result = apis.spotify.show_song_library(access_token=access_token, page_index=page_index, page_limit=page_limit)
    if not result['items']:
        break
    songs.extend(result['items'])
    page_index += 1
songs"}

{"code": "songs = []
