actions.command:
for song_id in removal_songs:
    apis.spotify.remove_song_from_library(access_token=token, song_id=song_id)
    print(f"Removed song {song_id} from library")

for playlist in playlists:
    playlist_id = playlist['playlist_id']
    for song_id in playlist['song_ids']:
        song_details = apis.spotify.show_song(access_token=token, song_id=song_id)
        release_year = int(song_details['release_date'].split('-')[0])
        if release_year < 2021:
            apis.spotify.remove_song_from_playlist(access_token=token, playlist_id=playlist_id, song_id=song_id)
            print(f"Removed song {song_id} from playlist {playlist_id}")

