actions.command:
for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    playlist_songs = playlist['song_ids']
    songs_to_remove = []

    for song_id in playlist_songs:
        song_details = apis.spotify.show_song(song_id=song_id, access_token=access_token)
        release_year = int(song_details['release_date'].split('-')[0])

        if release_year <= 2021:
            songs_to_remove.append(song_id)

    if songs_to_remove:
        removal_response = apis.spotify.remove_song_from_playlist(
            access_token=access_token, 
            playlist_id=playlist_id, 
            song_ids=songs_to_remove
        )
        print(f"Removed songs {songs_to_remove} from playlist {playlist_id}: {removal_response}")

