def extract_song_ids_from_albums(albums):
    song_ids = []
    for album in albums:
        song_ids.extend(album['song_ids'])
    return song_ids

all_song_ids = extract_song_ids_from_albums(albums)

user_email = profile['email']

for song_id in all_song_ids:
    try:
        # Check if the song is liked
        privates = apis.spotify.show_song_privates(song_id=song_id, access_token=token)
        if privates.get('liked', False):
            # Check existing reviews by the user
            reviews = apis.spotify.show_song_reviews(song_id=song_id, user_email=user_email, page_limit=1)
            if reviews:
                existing_rating = reviews[0]['rating']
                if existing_rating < 4:
                    # Update to 4 stars
                    apis.spotify.review_song(song_id=song_id, rating=4, access_token=token)
            else:
                # No existing review, create a 4-star review
                apis.spotify.review_song(song_id=song_id, rating=4, access_token=token)
    except Exception as e:
        print(f"Error processing song {song_id}: {e}")

