    dir_path = f"~/photographs/vacations/{dir_name}/"
    exists = apis.file_system.directory_exists(directory_path=dir_path, access_token=token)['exists']
    if not exists:
        print(f"Creating directory: {dir_path}")
        apis.file_system.create_directory(path=dir_path, access_token=token)
    else:
        print(f"Directory already exists: {dir_path}")

# Create required directories using correct parameter name
directories = ["Athens", "Seoul", "Paris"]
for dir_name in directories:
    dir_path = f"~/photographs/vacations/{dir_name}/"
    exists = apis.file_system.directory_exists(directory_path=dir_path, access_token=token)['exists']
    if not exists:
        print(f"Creating directory: {dir_path}")
        apis.file_system.create_directory(directory_path=dir_path, access_token=token)
    else:
        print(f"Directory already exists: {dir_path}")

# Process each file and move to appropriate directory based on creation date
target_dir_abs = "/home/susan/photographs/vacations/"
files = [entry for entry in directory_contents if entry.startswith(target_dir_abs) and not entry.endswith("/")]

for file_path in files:
    file_details = apis.file_system.show_file(file_path=file_path, access_token=token)
    created_at = file_details['created_at']
    year, month, _ = created_at.split('-')

    if year == '2023':
        if month == '01':
            dest_dir = "~/photographs/vacations/Athens/"
        elif month == '04':
            dest_dir = "~/photographs/vacations/Seoul/"
        else:
            dest_dir = "~/photographs/vacations/Paris/"
    else:
        dest_dir = "~/photographs/vacations/Paris/"

    apis.file_system.move_file(file_path=file_path, destination_directory_path=dest_dir, access_token=token)
    print(f"Moved {file_path} to {dest_dir}")

apis.supervisor.complete_task(status="success")

