actions.command:
# Follow only new artists after full pagination
new_artists = artist_ids - followed_ids
successful_follows = 0

for artist_id in new_artists:
    try:
        result = apis.spotify.follow_artist(artist_id=artist_id, access_token=spotify_token)
        if result.get('message') == 'Artist followed successfully':
            successful_follows += 1
    except Exception as e:
        print(f"Failed to follow artist {artist_id}: {str(e)}")

print(f"Successfully followed {successful_follows} new artists")
apis.supervisor.complete_task(status="success")

