function.arguments:
{"code": "songs = []
page_index = 0
page_limit = 20
while True:
    response = apis.spotify.show_song_library(access_token=token, page_index=page_index, page_limit=page_limit)
    if not response:
        break
    songs.extend(response)
    page_index += 1
print(f"Total songs in library: {len(songs)}")"}

{"code": "liked_songs = []
page_index = 0
page_limit = 20
while True:
    response = apis.spotify.show_liked_songs(access_token=token, page_index=page_index, page_limit=page_limit)
    if not response:
        break
    liked_songs.extend(response)
    page_index += 1
liked_song_ids = {song["song_id"] for song in liked_songs}
print(f"Number of liked songs: {len(liked_song_ids)}")"}

