# Extract liked album IDs for quick lookup
liked_album_ids = {album['album_id'] for album in liked_albums}

# Identify albums to remove
albums_to_remove = []
for album in album_library:
    album_id = album['album_id']
    if album_id not in liked_album_ids:
        albums_to_remove.append(album_id)
    else:
        # Get album details to check songs
        album_details = apis.spotify.show_album(access_token=token, album_id=album_id)
        album_songs = {song['id'] for song in album_details['songs']}
        # Check if all songs are downloaded
        if not album_songs.issubset(downloaded_song_ids):
            albums_to_remove.append(album_id)

# Execute removals
for album_id in albums_to_remove:
    apis.spotify.remove_album_from_library(access_token=token, album_id=album_id)

# Verify album library cleanup
updated_album_library = get_all_albums_in_library(token)
print(f"Album library now contains {len(updated_album_library)} albums")

