{"code": "artist_ids = set()
page_index = 0
while True:
    songs = apis.spotify.show_liked_songs(access_token=token, page_index=page_index)
    if not songs:
        break
    for song in songs:
        for artist in song['artists']:
            artist_ids.add(artist['id'])
    page_index += 1
print(f'Collected {len(artist_ids)} unique artist IDs: {sorted(artist_ids)}')"}

{"code": "for artist_id in sorted(artist_ids):
    try:
        response = apis.spotify.follow_artist(artist_id=artist_id, access_token=token)
