actions.command:
# Filter electricity bill files for 2023
electricity_bills = [f for f in bills_dir if f.startswith("/home/james/bills/electricity/2023-") and f.endswith(('.txt', '.pdf'))]

total_cost = 0.0

for bill_file in electricity_bills:
    file_content = apis.file_system.show_file(file_path=bill_file, access_token=access_token)
    if bill_file.endswith('.txt'):
        # Decode base64 content for text files
        import base64
        try:
            text_content = base64.b64decode(file_content['content'].split('binary:')[1]).decode('utf-8')
            if 'Total' in text_content:
                amount_str = text_content.split('Total: $')[1].split('\n')[0]
                total_cost += float(amount_str)
        except Exception as e:
            print(f"Error processing {bill_file}: {e}")

print(f"Total electricity cost for this year: ${total_cost:.2f}")

