user_email = "jes.mill@gmail.com"

for album in albums:
    for song_id in album['song_ids']:
        song_privates = apis.spotify.show_song_privates(access_token=token, song_id=song_id)

        if song_privates.get('liked', False):
            song_details = apis.spotify.show_song(access_token=token, song_id=song_id)
            reviews = apis.spotify.show_song_reviews(access_token=token, song_id=song_id)

            # Find user's existing review
            user_review = next((r for r in reviews if r['user']['email'] == user_email), None)

            if user_review:
                if user_review['rating'] < 4:
                    apis.spotify.update_song_review(
                        access_token=token,
                        song_review_id=user_review['song_review_id'],
                        rating=4
                    )
                    print(f"Updated {song_details['title']} to 4 stars")
            else:
                apis.spotify.review_song(access_token=token, song_id=song_id, rating=4)
                print(f"Created 4-star review for {song_details['title']}")

