actions.command:
for playlist in playlists:
    playlist_id = playlist['playlist_id']
    current_playlist = apis.spotify.show_playlist(access_token=token, playlist_id=playlist_id)
    for song in current_playlist['songs']:
        song_id = song['id']
        song_details = apis.spotify.show_song(access_token=token, song_id=song_id)
        release_year = int(song_details['release_date'].split('-')[0])
        if release_year > 2021:
            response = apis.spotify.remove_song_from_playlist(access_token=token, playlist_id=playlist_id, song_id=song_id)
            print(f"Removed song {song_id} from playlist {playlist_id}: {response}")
        else:
            print(f"Song {song_id} in playlist {playlist_id} is from {release_year}, no action.")

