page_index = 0
page_limit = 50
while True:
    response = apis.spotify.show_playlist_library(access_token=token, page_index=page_index, page_limit=page_limit)
    if not response:
        break
    all_playlists.extend(response)
    if len(response) < page_limit:
        break
    page_index += 1
print(len(all_playlists), "playlists retrieved")"}

{"code": "all_playlists = []
