print(len(all_playlists), "playlists retrieved")"}

{"code": "max_duration = 0
for playlist in all_playlists:
    song_ids = playlist['song_ids']
    total_seconds = 0
    for song_id in song_ids:
        song = apis.spotify.show_song(song_id=song_id, access_token=token)
        total_seconds += song['duration']
    minutes = round(total_seconds / 60)
    if minutes > max_duration:
        max_duration = minutes
print(max_duration)"}

