actions.command:
# Find current song's position in the queue
current_position = None
for song in queue:
    if song['is_current']:
        current_position = song['position']
        break

# Like all songs up to and including the current one
for song in queue:
    if song['position'] <= current_position:
        apis.spotify.like_song(song_id=song['song_id'], access_token=token)
        print(f"Liked song ID {song['song_id']}: {song['title']}")

