{"code": "min_duration = float('inf')

for playlist in playlists:
    total_duration = 0
    for song_id in playlist['song_ids']:
        song = apis.spotify.show_song(song_id=song_id, access_token=token)
        duration = song['duration']  # Assume duration is in seconds
        total_duration += duration
    if total_duration < min_duration:
        min_duration = total_duration

# Convert to minutes and round
shortest_playlist_minutes = round(min_duration / 60)
print(f"Minimum duration in seconds: {min_duration}")
print(f"Shortest playlist length in minutes: {shortest_playlist_minutes}")"}

