{"code": "oldest_release_date = None
oldest_song_title = None

# Process song library
page_index = 0
page_limit = 20
while True:
    songs = apis.spotify.show_song_library(access_token=token, page_index=page_index, page_limit=page_limit)
    if not songs:
        break
    for song in songs:
        song_id = song['song_id']
        song_details = apis.spotify.show_song(song_id=song_id, access_token=token)
        release_date = song_details['release_date']
        if oldest_release_date is None or release_date < oldest_release_date:
            oldest_release_date = release_date
            oldest_song_title = song_details['title']
    if len(songs) < page_limit:
        break
    page_index += 1

print(f"Oldest song from songs: {oldest_song_title} released on {oldest_release_date}")"}

{"code": "oldest_release_date = '2019-04-28T14:55:58'
oldest_song_title = 'Dancing on the Precipice of Love'

# Process album library
page_index = 0
page_limit = 20
while True:
    albums = apis.spotify.show_album_library(access_token=token, page_index=page_index, page_limit=page_limit)
    if not albums:
        break
    for album in albums:
        album_id = album['album_id']
        album_details = apis.spotify.show_album(album_id=album_id, access_token=token)
        release_date = album_details['release_date']
        if oldest_release_date is None or release_date < oldest_release_date:
            oldest_release_date = release_date
            oldest_song_title = album_details['title']
    if len(albums) < page_limit:
        break
    page_index += 1

print(f"Oldest song from albums: {oldest_song_title} released on {oldest_release_date}")"}

