artist_ids_to_follow = set()

for song_id in all_song_ids:
    song = apis.spotify.show_song(access_token=token, song_id=song_id)
    if song['genre'].lower() == 'indie':
        for artist in song['artists']:
            artist_ids_to_follow.add(artist['id'])

print(sorted(artist_ids_to_follow))

for artist_id in [19, 35, 36]:
    apis.spotify.follow_artist(access_token=token, artist_id=artist_id)
    print(f"Followed artist ID {artist_id}")

