# Process remaining unliked songs
for song in unliked_songs[1:]:  # Skip index 0 (already processed song 12)
    song_id = song['song_id']
    user_email = profile['email']

    # Fetch all reviews for current song
    reviews = []
    page_index = 0
    page_limit = 20
    while True:
        response = apis.spotify.show_song_reviews(access_token=token, song_id=song_id, page_index=page_index, page_limit=page_limit)
        if not response:
            break
        reviews.extend(response)
        if len(response) < page_limit:
            break
        page_index += 1

    # Find user's review
    user_review = None
    for review in reviews:
        if review['user']['email'] == user_email:
            user_review = review
            break

    if user_review:
        if user_review['rating'] > 1:
            # Update to 1 star with correct parameter name
            apis.spotify.update_song_review(access_token=token, review_id=user_review['song_review_id'], rating=1)
            print(f"Updated song {song_id} to 1-star")
        else:
            print(f"Song {song_id} already has 1-star")
    else:
        # Create new 1-star review
        apis.spotify.review_song(access_token=token, song_id=song_id, rating=1)
        print(f"Created 1-star for song {song_id}")

